+// filterAdminActions removes any policy statements that grant admin:* actions unless explicitly allowed.
+func filterAdminActions(policyData []byte) []byte {
+	sp, err := policy.ParseConfig(bytes.NewReader(policyData))
+	if err != nil || sp == nil {
+		return policyData
+	}
+	var filteredStatements []policy.Statement
+	for _, stmt := range sp.Statements {
+		var hasAdminAction bool
+		for _, action := range stmt.Actions {
+			if len(action) >= 6 && action[:6] == "admin:" {
+				hasAdminAction = true
+				break
+			}
+		}
+		if !hasAdminAction {
+			filteredStatements = append(filteredStatements, stmt)
+		}
+	}
+	if len(filteredStatements) == len(sp.Statements) {
+		return policyData // No admin actions found, return as is
+	}
+	sp.Statements = filteredStatements
+	filtered, err := json.Marshal(sp)
+	if err != nil {
+		return policyData
+	}
+	return filtered
+}
+
