+// sanitizeRsyncArgs checks and filters rsync arguments to prevent dangerous options
+func sanitizeRsyncArgs(args []string) ([]string, error) {
+	// List of forbidden rsync options that can lead to command injection or privilege escalation
+	forbidden := map[string]struct{}{
+		"--rsh": {}, "-e": {}, "--rsync-path": {}, "--iconv": {}, "--exec": {}, "--protect-args": {},
+		"--files-from": {}, "--from": {}, "--to": {}, "--address": {}, "--remote-option": {}, "--sockopts": {},
+		"--chmod": {}, "--chown": {}, "--usermap": {}, "--groupmap": {}, "--super": {}, "--fake-super": {},
+		"--perms": {}, "--owner": {}, "--group": {}, "--devices": {}, "--specials": {}, "--copy-devices": {},
+		"--copy-links": {}, "--copy-unsafe-links": {}, "--copy-dirlinks": {}, "--link-dest": {}, "--copy-dest": {},
+		"--compare-dest": {}, "--partial-dir": {}, "--temp-dir": {}, "--out-format": {}, "--log-file": {},
+		"--log-file-format": {}, "--password-file": {}, "--config": {}, "--daemon": {}, "--server": {},
+		"--write-devices": {}, "--read-devices": {}, "--sparse": {}, "--inplace": {}, "--preallocate": {},
+		"--fuzzy": {}, "--delete": {}, "--delete-excluded": {}, "--delete-after": {}, "--delete-before": {},
+		"--delete-during": {}, "--delete-delay": {}, "--remove-source-files": {}, "--force": {}, "--ignore-errors": {},
+		"--max-delete": {}, "--max-size": {}, "--min-size": {}, "--max-alloc": {}, "--max-verbosity": {},
+		"--no-motd": {}, "--no-whole-file": {}, "--whole-file": {}, "--no-blocking-io": {}, "--blocking-io": {},
+		"--no-inc-recursive": {}, "--inc-recursive": {}, "--no-dirs": {}, "--dirs": {}, "--no-implied-dirs": {},
+		"--implied-dirs": {}, "--no-relative": {}, "--relative": {}, "--no-strip": {}, "--strip": {},
+		"--no-owner": {}, "--no-group": {}, "--no-perms": {}, "--no-devices": {}, "--no-specials": {},
+		"--no-copy-devices": {}, "--no-copy-links": {}, "--no-copy-unsafe-links": {}, "--no-copy-dirlinks": {},
+		"--no-link-dest": {}, "--no-copy-dest": {}, "--no-compare-dest": {}, "--no-partial-dir": {}, "--no-temp-dir": {},
+		"--no-out-format": {}, "--no-log-file": {}, "--no-log-file-format": {}, "--no-password-file": {}, "--no-config": {},
+		"--no-daemon": {}, "--no-server": {}, "--no-write-devices": {}, "--no-read-devices": {}, "--no-sparse": {},
+		"--no-inplace": {}, "--no-preallocate": {}, "--no-fuzzy": {}, "--no-delete": {}, "--no-delete-excluded": {},
+		"--no-delete-after": {}, "--no-delete-before": {}, "--no-delete-during": {}, "--no-delete-delay": {},
+		"--no-remove-source-files": {}, "--no-force": {}, "--no-ignore-errors": {}, "--no-max-delete": {}, "--no-max-size": {},
+		"--no-min-size": {}, "--no-max-alloc": {}, "--no-max-verbosity": {}, "--no-no-motd": {},
+	}
+	var sanitized []string
+	for _, arg := range args {
+		// Only check for exact matches and for options with values (e.g., --rsh=)
+		if _, found := forbidden[arg]; found {
+			return nil, errors.New("forbidden rsync option: " + arg)
+		}
+		for key := range forbidden {
+			if strings.HasPrefix(arg, key+"=") {
+				return nil, errors.New("forbidden rsync option: " + arg)
+			}
+		}
+		sanitized = append(sanitized, arg)
+	}
+	return sanitized, nil
+}
